mapper.select:
SELECT (SELECT COUNT(*) FROM la_recharge_order o WHERE o.pay_status = 1 AND o.delete_time IS NULL AND (o.refund_status <> 1 OR o.refund_status IS NULL) AND o.pay_time BETWEEN #{q.startEpoch} AND #{q.endEpoch} ) AS orderCount, (SELECT ROUND(COALESCE(SUM(o.order_amount), 0), 2) FROM la_recharge_order o WHERE o.pay_status = 1 AND o.delete_time IS NULL AND (o.refund_status <> 1 OR o.refund_status IS NULL) AND o.pay_time BETWEEN #{q.startEpoch} AND #{q.endEpoch} ) AS revenue, (SELECT COUNT(DISTINCT CONCAT(cl.course_class_id, '-', cl.lesson_no)) FROM la_course_consume_log cl JOIN la_course_class c ON c.id = cl.course_class_id AND c.is_delete = 0 LEFT JOIN la_area a ON a.id = c.area_id AND a.delete_time IS NULL WHERE cl.create_time BETWEEN #{q.startEpoch} AND #{q.endEpoch}
) AS lessonCount, (SELECT COUNT(*) FROM la_course_consume_log cl JOIN la_course_class c ON c.id = cl.course_class_id AND c.is_delete = 0 LEFT JOIN la_area a ON a.id = c.area_id AND a.delete_time IS NULL WHERE cl.create_time BETWEEN #{q.startEpoch} AND #{q.endEpoch}
) AS servicePersons

mapper.sql:
FROM la_recharge_order o
LEFT JOIN la_course_class c ON c.id = o.course_class_id AND c.is_delete = 0
LEFT JOIN la_area a ON a.id = c.area_id AND a.delete_time IS NULL
LEFT JOIN la_community comm ON comm.id = COALESCE(NULLIF(c.community_id, 0), a.community_id)
LEFT JOIN la_instructor ins ON ins.id = c.instructor_id
LEFT JOIN la_student s ON s.id = o.student_id
WHERE o.pay_status = 1
  AND o.delete_time IS NULL
  AND (o.refund_status <> 1 OR o.refund_status IS NULL)
  AND o.pay_time BETWEEN #{q.startEpoch} AND #{q.endEpoch}

    AND c.instructor_id = #{q.instructorId}


    AND o.course_class_id = #{q.courseClassId}


    AND COALESCE(NULLIF(c.community_id, 0), a.community_id, 0) = #{q.communityId}


    AND COALESCE(c.area_id, 0) = #{q.areaId}


    AND (o.sn LIKE #{q.keyword}
         OR c.name LIKE #{q.keyword}
         OR s.name LIKE #{q.keyword})

FROM la_course_consume_log cl
JOIN la_course_class c ON c.id = cl.course_class_id AND c.is_delete = 0
LEFT JOIN la_area a ON a.id = c.area_id AND a.delete_time IS NULL
LEFT JOIN la_community comm ON comm.id = COALESCE(NULLIF(c.community_id, 0), a.community_id)
LEFT JOIN la_instructor ins ON ins.id = c.instructor_id
WHERE cl.create_time BETWEEN #{q.startEpoch} AND #{q.endEpoch}

    AND c.instructor_id = #{q.instructorId}


    AND cl.course_class_id = #{q.courseClassId}


    AND COALESCE(NULLIF(c.community_id, 0), a.community_id, 0) = #{q.communityId}


    AND COALESCE(c.area_id, 0) = #{q.areaId}


    AND c.name LIKE #{q.keyword}

SELECT t.community_id AS communityId, SUM(t.orderCount) AS orderCount, SUM(t.revenue) AS revenue, SUM(t.attends) AS attends FROM ( SELECT COALESCE(NULLIF(c.community_id, 0), a.community_id, 0) AS community_id, COUNT(*) AS orderCount, COALESCE(SUM(o.order_amount), 0) AS revenue, 0 AS attends FROM la_recharge_order o LEFT JOIN la_course_class c ON c.id = o.course_class_id AND c.is_delete = 0 LEFT JOIN la_area a ON a.id = c.area_id AND a.delete_time IS NULL WHERE o.pay_status = 1 AND o.delete_time IS NULL AND (o.refund_status <> 1 OR o.refund_status IS NULL) AND o.pay_time BETWEEN #{q.startEpoch} AND #{q.endEpoch}
AND COALESCE(NULLIF(c.community_id, 0), a.community_id, 0) = #{q.communityId}
AND COALESCE(c.area_id, 0) = #{q.areaId}
AND c.instructor_id = #{q.instructorId}
AND o.course_class_id = #{q.courseClassId}
GROUP BY COALESCE(NULLIF(c.community_id, 0), a.community_id, 0) UNION ALL SELECT COALESCE(NULLIF(c.community_id, 0), a.community_id, 0) AS community_id, 0 AS orderCount, 0 AS revenue, COUNT(*) AS attends FROM la_course_consume_log cl JOIN la_course_class c ON c.id = cl.course_class_id AND c.is_delete = 0 LEFT JOIN la_area a ON a.id = c.area_id AND a.delete_time IS NULL WHERE cl.create_time BETWEEN #{q.startEpoch} AND #{q.endEpoch}
AND COALESCE(NULLIF(c.community_id, 0), a.community_id, 0) = #{q.communityId}
AND COALESCE(c.area_id, 0) = #{q.areaId}
AND c.instructor_id = #{q.instructorId}
AND cl.course_class_id = #{q.courseClassId}
GROUP BY COALESCE(NULLIF(c.community_id, 0), a.community_id, 0) ) t GROUP BY t.community_id

SELECT t.area_id AS areaId, SUM(t.orderCount) AS orderCount, SUM(t.revenue) AS revenue, SUM(t.attends) AS attends FROM ( SELECT COALESCE(c.area_id, 0) AS area_id, COUNT(*) AS orderCount, COALESCE(SUM(o.order_amount), 0) AS revenue, 0 AS attends FROM la_recharge_order o LEFT JOIN la_course_class c ON c.id = o.course_class_id AND c.is_delete = 0 LEFT JOIN la_area a ON a.id = c.area_id AND a.delete_time IS NULL WHERE o.pay_status = 1 AND o.delete_time IS NULL AND (o.refund_status <> 1 OR o.refund_status IS NULL) AND o.pay_time BETWEEN #{q.startEpoch} AND #{q.endEpoch}
AND COALESCE(c.area_id, 0) = #{q.areaId}
AND COALESCE(NULLIF(c.community_id, 0), a.community_id, 0) = #{q.communityId}
AND c.instructor_id = #{q.instructorId}
AND o.course_class_id = #{q.courseClassId}
GROUP BY COALESCE(c.area_id, 0) UNION ALL SELECT COALESCE(c.area_id, 0) AS area_id, 0 AS orderCount, 0 AS revenue, COUNT(*) AS attends FROM la_course_consume_log cl JOIN la_course_class c ON c.id = cl.course_class_id AND c.is_delete = 0 LEFT JOIN la_area a ON a.id = c.area_id AND a.delete_time IS NULL WHERE cl.create_time BETWEEN #{q.startEpoch} AND #{q.endEpoch}
AND COALESCE(c.area_id, 0) = #{q.areaId}
AND COALESCE(NULLIF(c.community_id, 0), a.community_id, 0) = #{q.communityId}
AND c.instructor_id = #{q.instructorId}
AND cl.course_class_id = #{q.courseClassId}
GROUP BY COALESCE(c.area_id, 0) ) t GROUP BY t.area_id
